/** The machine-readable registries under `project-control/`.
 *
 *  These are the canonical form of every fact the documentation states. The
 *  Markdown is a view of them; SAHEL, the dashboards and `docs:check` all read
 *  the JSON. Keeping one canonical copy per fact is what stops the PRINCE2
 *  view, the ITIL view and the project dashboard from slowly disagreeing about
 *  how many risks are open.
 *
 *  Registries that already exist and are already generated by another owner —
 *  `MASTER_REGISTRY.json` (the screen registry, built by
 *  `app/scripts/build-registry.mjs`), `RISK_REGISTER.json`, `BLOCKERS.json`,
 *  `STATUS.json` — are NOT rewritten here. They are referenced. Regenerating
 *  someone else's registry from weaker evidence is how a documentation system
 *  starts lying.
 */
import { join } from 'node:path'
import { P } from '../lib/paths.mjs'
import { DOCUMENTATION_FINDINGS } from '../lib/findings.mjs'
import { writeJson } from '../lib/write.mjs'

const meta = (model, generator, sources) => ({
  generatedAt: model.generatedAt,
  generator: `tools/docs/generators/${generator}`,
  regenerate: 'npm run docs:generate',
  derivedFrom: sources,
  handEdit: 'Never. Edit the source, then regenerate.',
})

export function generateRegistries(model) {
  const out = (name) => join(P.control, name)

  writeJson(out('ENTITY_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['server/src/db/schema.ts']),
    totals: {
      entities: model.entities.length,
      tenantScoped: model.entities.filter((e) => e.tenantScoped).length,
      branchScoped: model.entities.filter((e) => e.branchScoped).length,
      softDelete: model.entities.filter((e) => e.softDelete).length,
      versioned: model.entities.filter((e) => e.versioned).length,
      audited: model.entities.filter((e) => e.audited).length,
      withMoneyColumns: model.entities.filter((e) => e.moneyColumns.length).length,
      rlsEnabled: model.entities.filter((e) => e.rlsEnabled).length,
      columns: model.entities.reduce((s, e) => s + e.columns.length, 0),
    },
    entities: model.entities,
  })

  writeJson(out('RELATIONSHIP_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['server/src/db/schema.ts']),
    caveat:
      'Only relationships marked DECLARED are backed by a database foreign key. INFERRED relationships are naming-convention links with no constraint behind them; referential integrity for those rests on application code and row-level security.',
    totals: {
      relationships: model.relationships.relationships.length,
      declared: model.relationships.declaredCount,
      inferred: model.relationships.inferredCount,
      orphanReferenceColumns: model.relationships.orphanReferences.length,
    },
    orphanReferences: model.relationships.orphanReferences,
    relationships: model.relationships.relationships,
  })

  writeJson(out('API_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', [
      'server/src/registry.ts',
      'server/src/routes/*.ts',
      'server/src/auth/routes.ts',
    ]),
    totals: {
      endpoints: model.api.length,
      generated: model.api.filter((e) => e.kind === 'GENERATED').length,
      explicit: model.api.filter((e) => e.kind === 'EXPLICIT').length,
      unauthenticated: model.api.filter((e) => e.authentication.startsWith('None')).length,
      withPermissionGuard: model.api.filter((e) => e.permissionModule && !String(e.permissionModule).startsWith('(')).length,
      idempotent: model.api.filter((e) => e.idempotent).length,
      withTests: model.api.filter((e) => (e.tests ?? []).length).length,
    },
    collections: model.collections,
    endpoints: model.api,
  })

  writeJson(out('PERMISSION_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['packages/contract/src/rbac.ts']),
    note: 'The server enforces this matrix directly (server/src/security/permissions.ts). The frontend copy is asserted identical by server/tests/rbac-parity.test.ts; frontend RBAC is not a security boundary.',
    actions: model.rbac.actions,
    roles: model.rbac.roles,
    modules: model.rbac.modules,
    dataScopes: model.rbac.scopes,
    roleMeta: model.rbac.roleMeta,
    segregationOfDuties: model.rbac.sod,
    fieldRedaction: model.rbac.hiddenFields,
    totals: model.rbac.totals,
    matrix: model.rbac.matrix,
    cells: model.rbac.cells,
  })

  writeJson(out('BUSINESS_RULES.json'), {
    ...meta(model, 'registries.mjs', ['packages/contract/src/rules/*.ts']),
    note: 'Every entry names the function that enforces it. A rule with no function here is a rule nothing enforces.',
    totals: {
      rules: model.rules.length,
      guards: model.rules.filter((r) => r.kind === 'GUARD').length,
      calculations: model.rules.filter((r) => r.kind === 'CALCULATION').length,
      constants: model.rules.filter((r) => r.kind === 'CONSTANT').length,
    },
    rules: model.rules,
  })

  writeJson(out('STATE_MACHINE_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['packages/contract/src/entities/*.ts']),
    caveat:
      'Only lifecycles marked DECLARED_TRANSITION_TABLE have machine-readable legal transitions. STATE_SET_ONLY entries have a state enum but no declared transition table; their legal moves live in route handlers and rule guards, and are documented as such rather than invented.',
    totals: {
      machines: model.stateMachines.length,
      withDeclaredTransitions: model.stateMachines.filter((m) => m.transitionsDeclared).length,
      stateSetOnly: model.stateMachines.filter((m) => !m.transitionsDeclared).length,
    },
    machines: model.stateMachines,
  })

  writeJson(out('TEST_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['server/tests/**', 'app/e2e/**', 'app/tests/**', 'app/src/**/*.test.ts']),
    note: 'This catalogues what the suites contain, not whether they pass. Pass/fail is a dated, evidence-backed statement made only in docs/30_RELEASE_CERTIFICATION.',
    totals: {
      suites: model.tests.length,
      cases: model.tests.reduce((s, t) => s + t.caseCount, 0),
      byKind: Object.fromEntries(
        [...new Set(model.tests.map((t) => t.kind))].map((k) => [
          k,
          model.tests.filter((t) => t.kind === k).reduce((s, t) => s + t.caseCount, 0),
        ]),
      ),
    },
    suites: model.tests,
  })

  writeJson(out('CAPABILITY_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', [
      'packages/contract/src/rbac.ts',
      'project-control/MASTER_REGISTRY.json',
      'server/src/registry.ts',
    ]),
    note: 'Capabilities are built on permission modules and screen domains — the two taxonomies the implementation already agrees on — rather than on a third one that would immediately drift.',
    objectives: model.objectives,
    totals: {
      capabilities: model.capabilities.length,
      screensMapped: model.capabilities.reduce((s, c) => s + c.screenCount, 0),
      screensTotal: model.screens.length,
      endpointsMapped: model.capabilities.reduce((s, c) => s + c.endpointCount, 0),
      endpointsTotal: model.api.length,
    },
    capabilities: model.capabilities,
  })

  writeJson(out('SECURITY_REGISTRY.json'), {
    ...meta(model, 'registries.mjs', ['server/drizzle/*.sql', 'packages/contract/src/rbac.ts']),
    rowLevelSecurity: model.security,
    authenticationSurface: model.api
      .filter((e) => e.authentication.startsWith('None'))
      .map((e) => ({ method: e.method, path: e.path, source: e.source })),
  })

  writeJson(out('DOCUMENTATION_FINDINGS.json'), {
    ...meta(model, 'registries.mjs', ['tools/docs/lib/findings.mjs']),
    note:
      'Implementation findings surfaced while documenting the system, each verified against the source. Kept separate from FINDINGS.json, which engineering owns — a documentation generator appending to that register would make its provenance unclear and its regeneration destructive.',
    totals: {
      findings: DOCUMENTATION_FINDINGS.length,
      open: DOCUMENTATION_FINDINGS.filter((f) => f.status !== 'RESOLVED').length,
      high: DOCUMENTATION_FINDINGS.filter((f) => f.severity === 'HIGH' && f.status !== 'RESOLVED').length,
    },
    findings: DOCUMENTATION_FINDINGS,
  })

  return written(model)
}

function written(model) {
  return {
    entities: model.entities.length,
    endpoints: model.api.length,
    rules: model.rules.length,
    tests: model.tests.length,
  }
}
